def find_path(n, adj, target_length):
    """Find a path with at least target_length vertices (length = vertices - 1 edges)"""
    visited = set()

    def dfs(u):
        if len(visited) >= target_length - 1:
            return True, [u]

        visited.add(u)
        for v in adj[u]:
            if v not in visited:
                result, path = dfs(v)
                if result:
                    path = path + [u] if not result else path
                    return True, reversed(path) if not result else path

        visited.discard(u)
        return False, []

    # Try multiple starting points
    for start in random.sample(list(adj.keys()), min(n, len(adj))):
        visited.clear()
        ok, path = dfs(start)
        if ok and len(path) >= target_length - 1:
            return path
        visited.clear()

    return []

