from collections import deque, Counter

def solution(input_str):
    lines = input_str.strip().split('\n')
    a = list(map(int, lines[0].split()))
    b = list(map(int, lines[1].split()))

    if len(a) != len(b):
        return "-1"

    if sorted(a) != sorted(b):
        return "-1"

    a_parity = sorted(x % 2 for x in a)
    b_parity = sorted(x % 2 for x in b)

    if a_parity != b_parity:
        return "-1"

    start = tuple(sorted(a))
    target = tuple(sorted(b))

    if start == target:
        return "0"

    # BFS search
    visited = {start: []}
    queue = deque([start])

    while queue:
        state = queue.popleft()
        path = visited[state]

        if state == target:
            output = []
            output.append(str(len(path)))
            for op in path:
                output.append(f"{op[0]} {op[1]}")
            return "\n".join(output)

        if len(path) >= 1000:
            continue

        state_list = list(state)

        for i in range(len(state_list)):
            x = state_list[i]
            for j in range(len(state_list)):
                if i != j:
                    y = state_list[j]
                    new_x = 2 * y - x

                    if abs(new_x) > 10**18:
                        continue

                    new_state_list = state_list.copy()
                    new_state_list[i] = new_x
                    new_state = tuple(sorted(new_state_list))

                    if new_state not in visited:
                        visited[new_state] = path + [(x, y)]
                        queue.append(new_state)

    return "-1"

