        depth[u] = d
        parent[u] = p

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # Back edge found
                # Check if this creates a cycle of sufficient length
                if depth[u] - depth[v] + 1 >= k:
                    cycle = []
                    curr = u
