                        cycle.append(curr)
                        if curr == v:
                            break
                        curr = parent[curr]
                    found_cycle[0] = True
                    found_cycle_nodes = cycle
                    return
            if not visited[v]:
                dfs(v, u, d + 1)
                if found_cycle[0]:
                    return

