def solution(input_str: str) -> str:
    """
    Determines if Stepan's dissatisfaction can be exactly k.
    Input is a string with n k on first line and sequence on second line.
    """
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    if k == 0:
        # To have max consecutive N's = 0, we cannot have any 'N'
        # All '?' must be chosen as 'Y'
        if 'N' in s:
            return "NO\n"
        return "YES\n"

    # DP state: (max_consecutive_N_found_so_far, current_consecutive_N_ending_here)
    # Note: We cap max_consecutive at k since we only care about == k
    states: Set[Tuple[int, int]] = {(0, 0)}

    for char in s:
        new_states: Set[Tuple[int, int]] = set()
        for mx, curr in states:
            if char == 'Y':
                # Must treat as watched, current run breaks
                if mx <= k:
                    new_states.add((mx, 0))
            elif char == 'N':
                # Must treat as unwatched
                new_curr = curr + 1
                if new_curr <= k:
                    if new_curr <= mx:
                        new_states.add((mx, new_curr))
                    else:
                        new_states.add((new_curr, new_curr))
            else:  # char == '?'
                # Try treating as watched ('Y')
                if mx <= k:
                    new_states.add((mx, 0))

                # Try treating as unwatched ('N')
                new_curr = curr + 1
                if new_curr <= k:
                    if new_curr <= mx:
                        new_states.add((mx, new_curr))
                    else:
                        new_states.add((new_curr, new_curr))

        states = new_states

    # Check if any state has maximum exactly k
    for mx, _ in states:
        if mx == k:
            return "YES\n"

    return "NO\n"

