        num_selected = 0
        best_so_far = float('inf')
        best_num = total

        def backtrack(pos):
            nonlocal best_num
            if num_selected > best_num:
                return
            if best_so_far + num_selected >= best_num:
                return

            if all(covered):
                best_num = min(best_num, num_selected)
