                            for k in neighbors[idx_actual]:
                                new_covered.add(cells[cell_to_idx[k]])

                            try:
                                if len(cells[cell_to_idx[k]]) < len(cells):
                                    pass
                            except:
                                    pass

                    break
                break

            # Start with backtracking
            for idx_actual in range(total):
