                    num_selected += 1
                    for k in range(len(cells[cell_to_idx[k]])):
                        mask = cells[cell_to_idx[k]]
                    for neighbor in neighbors[idx_actual]:
                        covered[cell_to_idx[neighbor]] = True

                    backtrack(pos + 1)

                    used[idx_actual] = False
                    num_selected -= 1
                    for neighbor in neighbors[idx_actual]:
                        covered[cell_to_idx[neighbor]] = False

        backtrack(0)
        min_domination = best_num if best_num < total else total
    else:
        # For larger grids, use the approximation: ceil(n*m / 5)
        # This is the domination number formula for grid graphs
        from math import ceil
        min_domination = ceil(total / 5)

    # The domination number is the minimum number of destination cells needed
    # Answer is total - minimum_domination
    return f"{total - min_domination}\n"


