def solution(input_str):
    input_data = input_str.strip().split('\n')
    q = int(input_data[0])

    def length_of_block(n):
        """Calculate length of string '123...n' (concatenation of 1 to n)"""
        total = 0
        digit_len = 1
        start = 1
        while True:
            end = min(n, start * 10 - 1)
            total += (end - start + 1) * digit_len
            if end == n:
                break
            start *= 10
            digit_len += 1
        return total

    def get_block_range(n):
        """Get cumulative position range of block n"""
        return sum(length_of_block(i) for i in range(1, n + 1))

    def find_digit_in_block(block_num, offset):
        """Find which digit is at position offset (1-indexed) in block `block_num`"""
        for i in range(1, block_num + 1):
            s = str(i)
            if offset <= len(s):
                return s[offset - 1]
            offset -= len(s)
        return ''

    results = []

    for i in range(1, q + 1):
        k = int(input_data[i])

        # Find which block k falls into
        current_pos = 0
        block = 1
        while True:
            block_len = length_of_block(block)
            if current_pos + block_len >= k:
                break
            current_pos += block_len
            block += 1

        # Now k falls in block `block`
        # Find offset within this block
        offset = k - current_pos

        # Find the digit at offset in this block
        digit = find_digit_in_block(block, offset)
        results.append(digit)

    return '\n'.join(results)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            x, y = map(int, lines[i].split())
            adj[x].append(y)
            adj[y].append(x)

    # Build connectivity information
    visited = [False] * (n + 1)
    components = []
    for i in range(1, n + 1):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            if comp:
                components.append(comp)

    # Function to count independent sets for a component
    def count_independent_sets(comp):
        k = len(comp)
        comp_set = set(comp)
        local_adj = [[] for _ in range(k)]
        for i, u in enumerate(comp):
            for v in adj[u]:
                if v in comp_set:
                    local_adj[i].append(comp.index(v))

        memo = {}

        def count(idx, forbidden_mask):
            if idx == k:
                return 1
            state = (idx, forbidden_mask)
            if state in memo:
                return memo[state]

            total = 0
            # Option 1: Don't include vertex idx in the set
            total += count(idx + 1, forbidden_mask)

            # Option 2: Include vertex idx in the set (if not forbidden)
            if not (forbidden_mask & (1 << idx)):
                new_mask = forbidden_mask | (1 << idx)
                # Mark all neighbors as forbidden
                for nei in range(idx + 1, k):
                    if local_adj[idx][idx] and (forbidden_mask >> local_adj[idx] & 1):
                        new_mask |= (1 << nei)
                total += count(idx + 1, new_mask)

            memo[state] = total
            return total

        return count(0, 0)

