    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    visited = [False] * (n + 1)
    bfs_order = []
    bfs_queue = deque([1])
    visited[1] = True

    while bfs_queue:
        u = bfs_queue.popleft()
        bfs_order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                bfs_queue.append(v)

    # dp[u][k] = max product of (completed subcomponent products) 
    #           when subtree u has a component of size k ending at u
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Process in reverse BFS order (bottom-up)
    for i in range(n - 1, -1, -1):
        u = bfs_order[i]

        # Initialize: component of just u, no completed subcomponents
        dp[u][1] = 1

        for v in children[u]:
            # Compute max contribution from child's subtree if edge is cut
            max_v_cut = 0
            for k in range(1, n + 1):
                if dp[v][k] > 0:
                    contribution = dp[v][k] * k
                    if contribution > max_v_cut:
                        max_v_cut = contribution

            # Current state before this child
            current_max = max(dp[u])
            if current_max == 0:
                current_max = 1

            # Merge child's results with current
            new_dp = [[0] * (n + 1) for _ in range(n + 1)]

            # Copy current states scaled by child's contribution max
            for s in range(1, n + 1):
                if dp[u][s] > 0:
                    new_dp[s][s] *= max_v_cut

            # Merge with each child state
            child_sums = range(1, n + 1)
            for s_u in range(1, n + 1):
                if dp[u][s_u] <= 0:
                    continue
                for s_v in range(1, n + 1):
                    if dp[v][s_v] <= 0:
                        continue
                    s_new = s_u + s_v
                    if s_new <= n:
                        val = dp[v][s_v] * dp[u][s_u]
                        if new_dp[s_new] < val:
                            new_dp[s_new] = val

            for s in range(1, n + 1):
                if dp[u][s] > 0:
                    for s_v in range(1, n + 1):
                        if dp[v][s_v] > 0:
                            if s + s_v <= n:
                                val = dp[u][s] * dp[v][s_v]
                                if new_dp[s + s_v] < val:
                                    new_dp[s + s_v] = val

            o = dict(zip(dp[u], max_v_cut))
            for s in range(1, n + 1):
                if s > n:
                    continue
                dp[u][s] = o.get(s, 0)

