    for i in range(1, n):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Build tree (parents and children via BFS from root 1)
    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    bfs_order = []
    queue = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while queue:
        u = queue.pop(0)
        bfs_order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                queue.append(v)

    # dp[u][k] = maximum product of completed subcomponents in subtree u,
    #           when the component containing u has size k (still open)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Process bottom-up
    for i in range(n - 1, -1, -1):
        u = bfs_order[i]

        # Base: u alone, size 1, product 1
        dp[u][1] = 1

        for v in children[u]:
            old_u = dp[u][:]
            old_v = dp[v][:]

            # Get max contribution from v's subtree if cut
            max_cut_v = 1
            for k in range(1, len(dp[v])):
                if old_v[k] > 0:
                    contrib = old_v[k] * k
                    if contrib > max_cut_v:
                        max_cut_v = contrib

            # New DP table after merging v
            new_ui = len(old_u)
            new_dp = [[0] * len(old_u) for _ in range(old_u)]

            # Option 1: Cut edge to v
            for s in range(1, new_dp):
                if old_u[s] > 0:
                    val = old_u[s] * max_cut_v
                    if val > new_dp[s]:
                        new_dp[s] = val

            # Option 2: Keep edge to v
            for s_u in range(1, new_ui):
                if old_u[s_u] <= 0:
                    continue
                for s_v in range(1, new_ui):
                    if old_v[s_v] > 0:
                        s_new = s_u + s_v
                        if s_new <= new_ui:
                            val = old_u[s_u] * old_v[s_v]
                            if val > new_dp[s_new]:
                                new_dp[s_new] = val

            dp[u] = new_dp

    # Answer: max product considering the root's component
    ans = 1
    for k in range(1, n + 1):
        if dp[1][k] > 0:
            ans = max(ans, dp[1][k] * k)

    return str(ans)


