                for d in days:
                    if d <= D:
                        last_day = max(last_day, d)
                last_sale_day.append((last_day, i))
            else:
                # No sale opportunity, will buy at full price
                last_sale_day.append((D + 1, i))

        # Sort by last sale day (earliest first for greedy)
        last_sale_day.sort()

        # Greedy: process items in order of deadline
        # Items bought on sale by day D
        # Remaining bought at full price (cost 2)

        current_day = D
        current_money = D  # Total money by day D

        # Count items bought on sale
        bought_on_sale = 0
        bought_daily = {}

        for last_day, item_idx in last_sale_day:
            if last_day <= D:
                # This item has a sale within [1, D]
                qty = k[item_idx]
                if qty > 0:
                    # We need to buy this item
                    # The key insight: process items with earlier deadlines first
                    # because those are more urgent
                    found_day = -1
                    for d in offer_days[item_idx]:
                        if d <= D and d == last_day:
                            found_day = d
                            break

                    if found_day == -1:
                        continue  # No sale this time

                    if found_day not in bought_daily:
