                if items_remaining[idx] > 0:
                    purchase_days.append((d, idx))

        purchase_days.sort()

        current_money = 0
        total_bought = 0

        for d, idx in purchase_days:
            # Money earned by day d
            current_money += 1
            items_bought = items_remaining[idx]
            if items_bought > 0:
                total_bought += items_bought
                items_remaining[idx] = 0
                current_money -= 1
                if items_remaining[idx] <= 0:
                    items_remaining[idx] = 0

        # Buy remaining items at full price (cost 2 each)
        for i in range(n):
            if items_remaining[i] > 0:
                cost = items_remaining[i] * 2
                if current_money >= cost:
                    current_money -= cost
                else:
