        # Check if all items bought on sale or can be bought remaining
        for i in range(n):
            if items_remaining[i] > 0:
                return False

        return True

    # Binary search for minimum day
    left, right = 1, 400005  # Upper bound: worst case buying all at full price
    result = right

    while left <= right:
        mid = (left + right) // 2
        if check(mid):
