            if op == 'R':
                # Shift columns right (last column moves to front for each row)
                for i in range(n):
                    if n > 1:
                        matrix[i] = matrix[i][1:] + matrix[i][:1]
            elif op == 'L':
                # Shift columns left (first column moves to end)
                for i in range(n):
                    if n > 1:
                        matrix[i] = matrix[i][-1] + matrix[i][:-1]
            elif op == 'D':
                # Shift rows down (last row moves to front)
                if n > 1:
                    matrix = [matrix[n-1]] + matrix[:-1]
            elif op == 'U':
                # Shift rows up (first row moves to end)
                if n > 1:
                    matrix = matrix[1:] + [matrix[0]]
